/// Returns the byte table of one canonical single-byte encoding.
pub(super) fn single_byte_table(canonical: &str) -> Option<&'static SingleByteTable> {
    match canonical {
        "ASCII" => Some(&SB_ASCII),
        "7bit" => Some(&SB_7BIT),
        "8bit" => Some(&SB_8BIT),
        "ISO-8859-1" => Some(&SB_ISO_8859_1),
        "ISO-8859-2" => Some(&SB_ISO_8859_2),
        "ISO-8859-3" => Some(&SB_ISO_8859_3),
        "ISO-8859-4" => Some(&SB_ISO_8859_4),
        "ISO-8859-5" => Some(&SB_ISO_8859_5),
        "ISO-8859-6" => Some(&SB_ISO_8859_6),
        "ISO-8859-7" => Some(&SB_ISO_8859_7),
        "ISO-8859-8" => Some(&SB_ISO_8859_8),
        "ISO-8859-9" => Some(&SB_ISO_8859_9),
        "ISO-8859-10" => Some(&SB_ISO_8859_10),
        "ISO-8859-13" => Some(&SB_ISO_8859_13),
        "ISO-8859-14" => Some(&SB_ISO_8859_14),
        "ISO-8859-15" => Some(&SB_ISO_8859_15),
        "ISO-8859-16" => Some(&SB_ISO_8859_16),
        "Windows-1251" => Some(&SB_WINDOWS_1251),
        "Windows-1252" => Some(&SB_WINDOWS_1252),
        "Windows-1254" => Some(&SB_WINDOWS_1254),
        "CP866" => Some(&SB_CP866),
        "CP850" => Some(&SB_CP850),
        "KOI8-R" => Some(&SB_KOI8_R),
        "KOI8-U" => Some(&SB_KOI8_U),
        "ArmSCII-8" => Some(&SB_ARMSCII_8),
        _ => None,
    }
}
